import{z as B,x as A,o,c as p,q as r,j as n,D as i,d as e,s,S as t,b as l}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"轮询 I/O","description":"","frontmatter":{"title":"轮询 I/O","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/io-polling.md","filePath":"cs/io-polling.md","lastUpdated":1791063341000}'),d={name:"cs/io-polling.md"};function c(C,a,u,m,D,I){const E=A("Mermaid");return o(),p("div",null,[a[2]||(a[2]=r('<h1 id="轮询-i-o" tabindex="-1">轮询 I/O <a class="header-anchor" href="#轮询-i-o" aria-label="Permalink to &quot;轮询 I/O&quot;">​</a></h1><div class="epigraph"><p>当完成已在微秒级，进中断再调度的税可能大于等一轮门铃；轮询让提交线程自己收 CQ。</p><footer>—— 据 Linux blk-mq poll / io_uring IOPOLL 文档；NVMe 规范对完成队列的说明</footer></div><p><a href="/cs/dax-pmem">上一课</a>甚至没有完成队列。<a href="/cs/nvme-driver">NVMe</a> 默认 MSI-X：延迟 = 设备 + 中断 + 软中断 + 唤醒。<a href="/cs/posix-aio">POSIX AIO</a> 没解决这条。缺口是 <strong>轮询 I/O</strong>：谁在转、何时混合中断。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>高 IOPS 时中断风暴。<code>nvme poll</code> 或 io_uring <code>IORING_SETUP_IOPOLL</code>：提交后在 CQ 上转，直到完成或让出。缺口：要独占 CPU；低负载浪费能源；与 <a href="/cs/blk-schedulers">blk 调度</a> 的 none 常一起用；缓冲 I/O 难以 poll（完成路径在缓存）。本课对象是块层/uring 轮询，不是网卡 NAPI——NAPI 在网络课。</p><p><span class="marginnote">hipri 轮询队列、混合模式（超时才中断）是工程旋钮。教学上：完成通知从 IRQ 换成 busy-wait。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>应用提交 uring SQE（DIRECT 文件或 nvme），内核把命令进 SQ，线程在 <code>io_cqring</code> 或驱动 <code>poll</code> 钩上转。对照中断路径：无 <code>irq_handler</code>、少一次调度。对照 DAX：根本无 CQ。对照 SCSI：HBA 是否支持轮询因卡而异。</p>',8)),(o(),n(t,null,{default:i(()=>[s(E,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20SUB%5B%22%E6%8F%90%E4%BA%A4%E5%91%BD%E4%BB%A4%22%5D%20--%3E%20SQ%5B%22NVMe%20SQ%22%5D%0A%20%20SQ%20--%3E%20CQ%5B%22CQ%20%E5%8F%AF%E8%83%BD%E5%B7%B2%E6%9C%89%E5%AE%8C%E6%88%90%22%5D%0A%20%20IRQ%5B%22%E4%B8%AD%E6%96%AD%E8%B7%AF%E5%BE%84%22%5D%20-.-%3E%7C%22%E8%B7%B3%E8%BF%87%22%7C%20POLL%5B%22%E7%BA%BF%E7%A8%8B%E8%BD%AE%E8%AF%A2%20CQ%22%5D%0A%20%20POLL%20--%3E%20APP%5B%22%E7%94%A8%E6%88%B7%E6%94%B6%E5%AE%8C%E6%88%90%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l("h2",{id:"机制",tabindex:"-1"},[e("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=l("p",null,[e("轮询把尾延迟的软件部分压下去，用 CPU 换 IRQ。这是存储栈与后课网络旁路的共同主题。不要写成实时 FIFO 保证：轮询线程仍可能被抢占，除非隔核与 PREEMPT_RT 后课。能源：空转 C-state 进不去，"),l("a",{href:"/cs/cpuidle-cstate"},"cpuidle"),e(" 会再出现。")],-1)),a[5]||(a[5]=l("p",null,"安全：用户轮询不授予绕过权限检查；只是完成路径。",-1)),a[6]||(a[6]=l("p",null,[e("实现上：hipri 轮询需要队列支持，且通常要求 O_DIRECT。线程被调度跑开则轮询变成「忙等别人的完成」，要绑核。混合模式在超时后降回中断，避免空转。 读法上只引用"),l("a",{href:"/cs/dax-pmem"},"上一课"),e("的结论，不把对象换成训练推理或限价簿。")],-1)),(o(),n(t,null,{default:i(()=>[s(E,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20APP%5B%22%E5%BA%94%E7%94%A8%E7%BA%BF%E7%A8%8B%E7%BB%91%E6%A0%B8%22%5D%20--%3E%20SUB%5B%22%E6%8F%90%E4%BA%A4%20SQE%20(O_DIRECT)%22%5D%0A%20%20SUB%20--%3E%20WAIT%5B%22%E5%9C%A8%20CQ%20%E9%97%A8%E9%93%83%E4%B8%8A%E7%A9%BA%E8%BD%AC%22%5D%0A%20%20WAIT%20--%3E%20DONE%7B%22%E5%AE%8C%E6%88%90%E6%9D%A1%E7%9B%AE%E5%87%BA%E7%8E%B0%3F%22%7D%0A%20%20DONE%20--%3E%7C%22%E5%90%A6%3A%20%E5%86%8D%E8%BD%AC%E4%B8%80%E8%BD%AE%22%7C%20WAIT%0A%20%20DONE%20--%3E%7C%22%E6%98%AF%22%7C%20REAP%5B%22%E5%BD%93%E5%9C%BA%E5%8F%96%E8%B5%B0%20completion%22%5D%0A%20%20TO%5B%22%E8%B6%85%E6%97%B6%E9%98%88%E5%80%BC%22%5D%20-.-%3E%7C%22%E6%B7%B7%E5%90%88%E6%A8%A1%E5%BC%8F%3A%20%E9%99%8D%E5%9B%9E%22%7C%20IRQ%5B%22%E6%94%B9%E8%B5%B0%E4%B8%AD%E6%96%AD%E8%B7%AF%E5%BE%84%22%5D%0A"})]),fallback:i(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<p><span class="marginnote">数字实例：NVMe 盘完成一次读只要约 20–50 微秒，而「中断 → 软中断 → 唤醒线程 → 重新调度」这条软件路径本身就要 5–10 微秒外加缓存变冷；设备越快，这笔税占比越高——100 微秒级的完成里税可能占一成，10 微秒级完成时占一半。</span></p><p><span class="marginnote">直觉类比：中断像外卖到了按门铃，你可以去睡（省电），但要被叫醒再缓一缓；轮询像你干脆站在门口盯着，外卖一到 0 秒接手，代价是你这 10 分钟哪儿也去不了、电（CPU）一直烧着。单少、到得快时守门划算，单多时守门的人手根本不够。</span></p><p><span class="marginnote">常见误区：初学者容易以为轮询能保证「最低延迟」。实际上轮询线程照样可能被内核抢占，一被抢走 CQ 上别人攒的完成它就白转了；要稳定收益必须绑核隔离，而不是设个 flag 就完事。</span></p><p>本课在操作系统进阶的「存储栈 / 块层到设备」课序里，对象是 <strong>轮询 I/O</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 io_uring 全部 opcode 写成手册。不保证虚拟机里轮询有效（要半虚拟 poll 队列）。下一课用 cgroup 限制这块带宽：blkio。</p><p>版本字段会变，课序钉的是机制对象「轮询 I/O」，不是某一主线内核的结构体名。 后课默认：完成可以靠轮询收取。按组限制 IOPS/带宽，下一课 blkio cgroup。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>轮询用 CPU 收 CQ，去掉中断唤醒。</li><li>适合 DIRECT 高 IOPS；低负载不合适。</li><li>blkio 限制是下一课。</li><li>出处：Linux io_uring IOPOLL；NVMe；blk-mq poll。</li></ul>',10))])}const _=B(d,[["render",c]]);export{h as __pageData,_ as default};
